package main

import (
	"fmt"
	art "github.com/plar/go-adaptive-radix-tree/v2"
)

func main() {
	// Initialize a new Adaptive Radix Tree
	tree := art.New()

	// Insert key-value pairs into the tree
	tree.Insert(art.Key("apple"), "A sweet red fruit")
	tree.Insert(art.Key("application"), "A software program")
	tree.Insert(art.Key("apply"), "To put to use")
	tree.Insert(art.Key("banana"), "A long yellow fruit")
	tree.Insert(art.Key("cherry"), "A small red fruit")

	fmt.Println("All keys in the tree:")
	tree.ForEach(func(node art.Node) bool {
		fmt.Printf("Key: %s, Value: %s\n", node.Key(), node.Value())
		return true
	})

	fmt.Println("\nKeys with prefix 'app':")
	tree.ForEachPrefix(art.Key("app"), func(node art.Node) bool {
		fmt.Printf("Key: %s, Value: %s\n", node.Key(), node.Value())
		return true
	})

	fmt.Println("\nKeys with prefix 'ban':")
	tree.ForEachPrefix(art.Key("ban"), func(node art.Node) bool {
		fmt.Printf("Key: %s, Value: %s\n", node.Key(), node.Value())
		return true
	})

	fmt.Println("\nKeys with prefix 'xyz' (non-existent):")
	tree.ForEachPrefix(art.Key("xyz"), func(node art.Node) bool {
		fmt.Printf("Key: %s, Value: %s\n", node.Key(), node.Value())
		return true
	})
}
EOF
